void HairDyes()
{
    auto source=f::Catalog();
    for(unsigned color=0;color<6;++color){auto base=*std::ranges::find(source.items,item_catalog_fixture::InstantPotion(),&ItemBaseRow::key);base.key=ItemKey::Create(5,49500+color).value();base.contentCode="character.hair_dye_"+std::to_string(color);base.maxStack=10;source.items.push_back(base);source.consumables.push_back({base.key,0,{},{},{},{},{},true});source.characterServices.push_back({base.key,CharacterServiceKind::HairDye,1,color+1,0,1001});}
    const auto c=BuildItemCatalog(source).value();const ItemOwnerFence fence{pf::Character(),7,1};const std::array layouts{pf::Inventory()};auto facts=f::Facts();facts.characterLevel=30;
    for(unsigned color=0;color<6;++color){
        const auto key=ItemKey::Create(5,49500+color).value();const std::array ids{ItemInstanceId::Create(99500+color).value()};const auto grant=MakeGrantCommit(*c,{0xC1,static_cast<std::uint8_t>(color)},fence,layouts,{},ItemGrant{key,0,2},ids).value();const std::array items{grant.items[0].after};
        BookCharacter live;live.experience=111;live.alignment=222;live.statResetCredits=3;live.points[0]=4;live.progression=CharacterProgression{30,1,7,11,13};live.hair=CharacterHairState{5,0};BookLearning before;
        auto use=MakeCharacterServiceCommit(*c,{0xC2,static_cast<std::uint8_t>(color)},fence,layouts,items,before,live,ids[0],facts);Check(use && use->result.after==color && use->result.nextDyeLevel==(color ? 30 : 0),"all six fixed original colors and bleaching cooldown policy");Check(use->commit.items[0].after.count==1 && use->commit.learning->after.character.hair==CharacterHairState{color,static_cast<std::uint16_t>(color ? 30 : 0)},"exact source debit and hair state form one commit");auto expected=live;expected.hair=use->commit.learning->after.character.hair;Check(use->commit.learning->after.character==expected,"dye preserves every unrelated progression and point field");
        const auto ready=EncodeBookRuntime(*c,{1,255,123,456,1000,&items[0],&before,live,facts}).value();Check(std::to_integer<unsigned>(ready[5])==5 && std::to_integer<unsigned>(ready[54])==3,"hair service has explicit GC244 v5 discriminator");const auto done=EncodeBookRuntime(*c,{3,255,123,456,1000,&items[0],&use->commit.learning->after,use->commit.learning->after.character,facts,"",nullptr,{},nullptr,&use->result});Check(done.has_value(),"actual color result quotes original before and after without additive point math");
        auto saved=use->commit.learning->after;const auto encoded=EncodeBookLearning(saved).value();Check(encoded[3]=='5' && DecodeBookLearning(encoded).value()==saved,"BOK5 retains color and last-dye level exactly");
        if(color==0){for(unsigned mask=0;mask<8;++mask){auto variant=saved;if(!(mask&1))variant.character.progression.reset();if(!(mask&2))variant.character.alignment.reset();if(!(mask&4))variant.character.statResetCredits.reset();Check(DecodeBookLearning(EncodeBookLearning(variant).value()).value()==variant,"all BOK5 optional participant flag combinations");}for(std::size_t cut=0;cut<encoded.size();++cut)Check(!DecodeBookLearning(std::span(encoded).first(cut)),"every truncated hair checkpoint refused");auto bad=encoded;bad[2582]=7;Check(!DecodeBookLearning(bad),"BOK5 cannot omit mandatory hair flag");}
        auto bad=use->commit;bad.learning->after.character.hair->part=(color+1)%6;Check(!ValidateItemCommit(*c,bad),"forged target color refused");bad=use->commit;bad.items[0].after.count=2;Check(!ValidateItemCommit(*c,bad),"hair change without one item debit refused");bad=use->commit;bad.result[18]^=1;Check(!ValidateItemCommit(*c,bad),"forged saved dye level refused");
        live.hair->lastDyeLevel=28;auto early=PrepareCharacterService(*c,items[0],live,facts);Check(color ? !early && early.error()==SkillBookError::OnCooldown : early && early->nextDyeLevel==0,"two-level gap refuses ordinary dye while bleach always resets");live.hair->lastDyeLevel=27;Check(PrepareCharacterService(*c,items[0],live,facts).has_value(),"exact three-level boundary admits dye");live.hair->part=1001;Check(!PrepareCharacterService(*c,items[0],live,facts),"legacy costume hairstyle cannot be dyed");live.hair->part=5;auto costume=facts;costume.hairCostumeEquipped=true;Check(!PrepareCharacterService(*c,items[0],live,costume),"independent equipped native hair costume also blocks dye");live.hair.reset();Check(!PrepareCharacterService(*c,items[0],live,facts),"historical omitted hair checkpoint cannot invent initial state");
        live.hair=CharacterHairState{5,0};auto last=items;last[0].count=1;auto consumed=MakeCharacterServiceCommit(*c,{0xC3},fence,layouts,last,before,live,ids[0],facts).value();Check(consumed.commit.items[0].after.destroyed && !consumed.commit.items[0].after.placement && consumed.commit.learning->after.character.hair->part==color,"last source disappears without removing permanent hair state");
    }
}
